UPDATE tb_evento_corridas SET categorias='kids',url_regulamento='https://storagefileta.blob.core.windows.net/ticketagora/arquivos/evento/74828/4e91b6e5359b4b4389243a2939d996ff639199082801291559.pdf',descricao='A Maratona Monumental de Brasília 2026, organizada pela Monumental Eventos Esportivos, acontecerá na Esplanada dos Ministérios, também conhecida como Arena Monumental. O percurso da maratona passará pelos monumentos icônicos da capital. O evento inclui as distâncias de 42,2 km, 21,1 km, 10 km e 5 km, atraindo corredores de todo o Brasil. As inscrições estão abertas até o final de outubro de 2026 ou enquanto houver vagas. Idosos e pessoas com deficiência têm desconto de 50% no registro. Os kits variam de básico a black, oferecendo camisetas, números personalizados e medalhas, entre outros itens. Retirada dos kits ocorre de 19 a 21 de novembro em horários específicos, com possibilidade de estender o horário até às 17h para inscritos de fora do Distrito Federal. A retirada não será realizada no dia 22 de novembro de 2025. A maratona terá início em 21 de novembro de 2026, com largadas às 18h para corridas de 5 km e 10 km, e em 22 de novembro para a maratona e meia maratona a partir das 5h. A premiação será para os cinco primeiros colocados gerais, masculinos e femininos de cada distância, e para os três primeiros em faixas etárias.',descricao_en=NULL,descricao_es='La Marat&oacute;n Monumental de Bras&iacute;lia 2026, organizada por Monumental Eventos Esportivos, se llevar&aacute; a cabo en la Esplanada de los Ministerios, tambi&eacute;n conocida como Arena Monumental. El recorrido de la marat&oacute;n pasar&aacute; por los monumentos ic&oacute;nicos de la capital. El evento incluye las distancias de 42,2 km, 21,1 km, 10 km y 5 km, atrayendo corredores de todo Brasil. Las inscripciones est&aacute;n abiertas hasta finales de octubre de 2026 o mientras haya cupos disponibles. Los adultos mayores y personas con discapacidad tienen un descuento del 50&#x25; en el registro. Los kits var&iacute;an desde b&aacute;sico hasta black, ofreciendo camisetas, n&uacute;meros personalizados y medallas, entre otros art&iacute;culos. La entrega de los kits se realiza del 19 al 21 de noviembre en horarios espec&iacute;ficos, con posibilidad de extender el horario hasta las 17h para inscritos fuera del Distrito Federal. La entrega no se realizar&aacute; el d&iacute;a 22 de noviembre de 2025. La marat&oacute;n comenzar&aacute; el 21 de noviembre de 2026, con salidas a las 18h para las carreras de 5 km y 10 km, y el 22 de noviembre para la marat&oacute;n y media marat&oacute;n a partir de las 5h. La premiaci&oacute;n ser&aacute; para los cinco primeros lugares generales, masculinos y femeninos de cada distancia, y para los tres primeros en categor&iacute;as por edades.',descricao_traducoes_meta='{"es": {"description_hash": "5ede829fb4abac90fdb8c4d84d3b0d8d", "source_hash": "5118a8736284489d238a1fab5ccf6833"}}'::jsonb WHERE id_evento=39395;
